const HEADER_SIZE:     usize = 32;
const BYTES_PER_GLYPH: usize = 16;

pub fn draw_char(ch: u8, px: usize, py: usize, fg: u32, bg: u32) {
    let glyph_start = HEADER_SIZE + ch as usize * BYTES_PER_GLYPH;
    if glyph_start + BYTES_PER_GLYPH > FONT_DATA.len() { return; }
    let glyph = &FONT_DATA[glyph_start..glyph_start + BYTES_PER_GLYPH];
    let fr = ((fg >> 16) & 0xFF) as u8;
    let fg2 = ((fg >> 8)  & 0xFF) as u8;
    let fb  = ( fg        & 0xFF) as u8;
    let br = ((bg >> 16) & 0xFF) as u8;
    let bg2 = ((bg >> 8)  & 0xFF) as u8;
    let bb  = ( bg        & 0xFF) as u8;
    for row in 0..FONT_HEIGHT {
        let byte = glyph[row];
        for col in 0..FONT_WIDTH {
            if byte & (0x80 >> col) != 0 {
                crate::io::framebuffer::set_pixel(px + col, py + row, fr, fg2, fb);
            } else {
                crate::io::framebuffer::set_pixel(px + col, py + row, br, bg2, bb);
            }
        }
    }
}

pub fn draw_string(s: &str, mut px: usize, py: usize, fg: u32, bg: u32) {
    for b in s.bytes() { draw_char(b, px, py, fg, bg); px += FONT_WIDTH; }
}

pub fn draw_string_rgb(s: &str, mut px: usize, py: usize,
                        fg: (u8,u8,u8), bg: (u8,u8,u8)) {
    let fg32 = ((fg.0 as u32)<<16)|((fg.1 as u32)<<8)|fg.2 as u32;
    let bg32 = ((bg.0 as u32)<<16)|((bg.1 as u32)<<8)|bg.2 as u32;
    for b in s.bytes() { draw_char(b, px, py, fg32, bg32); px += FONT_WIDTH; }
}

/// UTF-8 string rendering with Romanian character support
pub fn draw_string_utf8(s: &str, mut px: usize, py: usize, fg: u32, bg: u32) {
    let bytes = s.as_bytes();
    let mut i = 0;
    while i < bytes.len() {
        let b0 = bytes[i];
        let (ch, advance) = if b0 < 0x80 {
            (b0, 1)
        } else if b0 & 0xE0 == 0xC0 && i + 1 < bytes.len() {
            let b1 = bytes[i+1];
            let cp = ((b0 as u32 & 0x1F) << 6) | (b1 as u32 & 0x3F);
            (utf8_to_font(cp), 2)
        } else if b0 & 0xF0 == 0xE0 && i + 2 < bytes.len() {
            let b1 = bytes[i+1]; let b2 = bytes[i+2];
            let cp = ((b0 as u32 & 0x0F)<<12)|((b1 as u32 & 0x3F)<<6)|(b2 as u32 & 0x3F);
            (utf8_to_font(cp), 3)
        } else {
            (b'?', 1)
        };
        draw_char(ch, px, py, fg, bg);
        px += FONT_WIDTH;
        i += advance;
    }
}

fn utf8_to_font(cp: u32) -> u8 {
    match cp {
        0x103 => 0xE3, // ă
        0x102 => 0xC3, // Ă
        0x00E2 => 0xE2, // â (latin small a circumflex)
        0x00C2 => 0xC2, // Â
        0x00EE => 0xEE, // î
        0x00CE => 0xCE, // Î
        0x015F => 0x9A, // ș
        0x015E => 0x8A, // Ș
        0x0163 => 0x9E, // ț
        0x0162 => 0x8E, // Ț
        n if n < 0x100 => n as u8,
        _ => b'?',
    }
}

pub fn init() {
    crate::serial_println!("  [FONT] embedded PSF2 8x16 (256 glyphs, ASCII+Romanian)");
}

